-- Change Kiev to Kyiv to reflect the Ukrainian-derived spelling, in keeping with the game's emphasis on City-States as distinct cultural entities
UPDATE Language_ru_RU
SET Text = 'Киев'
WHERE Tag = 'TXT_KEY_CITYSTATE_KIEV';

UPDATE Language_ru_RU
SET Text = 'Киевский'
WHERE Tag = 'TXT_KEY_CITYSTATE_KIEV_ADJ';

UPDATE Language_ru_RU
SET Text = 'Согласно легенде, Киев был основан тремя братьями-славянами - Кием, Щеком и Хоривом примерно в начале VI века нашей эры. С тех пор Киев, один из старейших городов Восточной Европы, пережил периоды великой славы и периоды относительной безвестности. Однако на протяжении веков он оставался важнейшим славянским культурным центром, сыграв ключевую роль в развитии средневековой восточнославянской цивилизации. [NEWLINE][NEWLINE]Расположенный на Днепровском торговом пути между Константинополем и Скандинавией, Киев попал под власть под контроль местной варяжской (варяжской) знати и стал ядром государства Русь. В течение 1000-х годов он достиг своего расцвета, став культурным центром с более чем 400 церквями, восемью рынками, доками, караван-сараем и великолепными домами. С основанием Киево-Могилянской академии в 1632 году город стал центром украинской учености и науки. Но как столица Киевской Руси город неоднократно подвергался разграблению и оккупации.[NEWLINE][NEWLINE]В 1667 году город стал частью Российской империи; Киев оставался церковным и культурным центром, но его политическое и экономическое влияние было маргинализировано. Киев пережил растущую «русификацию» в 1800-х годах в результате русской миграции, образовательной политики и индустриализации. Однако энтузиасты из числа этнических украинских дворян, офицеров и торговцев поддерживали местную культуру в Киеве, часто посредством подпольной деятельности, такой как книгопечатание, любительский театр, частные вечеринки, народные гуляния и тому подобное.[NEWLINE][NEWLINE]Насильственно включено В Советский Союз город пережил всевозможные бедствия: голод 1932–1933 годов опустошил низшие классы, сталинские чистки 1937–1938 годов почти уничтожили городскую интеллигенцию, а нацистское вторжение 1941–1943 годов принесло смерть. и разрушение. Но Киев устоял, и после распада Советского Союза в 1991 году была провозглашена независимая Украина с возрождающимся Киевом в качестве столицы и культурного центра.'
WHERE Tag = 'TXT_KEY_CIV5_KIEV_TEXT';

-- Update Hong Kong's Civilopedia entry to reflect increased Chinese control in 2020 onwards
UPDATE Language_ru_RU
SET Text = 'Город-государство в самом полном смысле этого слова, Гонконг — огромный город на южном побережье Китая. В наши дни в нём проживает более семи миллионов человек. Когда-то остров Гонконг и прилегающие к нему территории были домом для множества небольших поселений, включая основанные иностранными исследователями. Во времена китайской династии Цин в XIX веке торговые отношения с Англией ухудшились на фоне растущей обеспокоенности из-за ввоза в Китай индийского опиума. Британия надеялась компенсировать всё более дорогой импорт чая из Китая за счёт увеличения поставок опиума из своих индийских колоний. Однако правители Цин выступили против этого и попытались конфисковать поступающие партии опиума, что и спровоцировало Первую опиумную войну в 1839 году.[NEWLINE][NEWLINE]Будучи одной из ведущих морских держав эпохи, Британия без особого труда разгромила китайские силы и заняла остров Гонконг. После почти трёх лет конфликта подписание Нанкинского договора в 1842 году принесло Британии различные выгоды, включая контроль над Гонконгом. После более чем 150 лет существования в качестве британской колонии Гонконг в 1997 году был возвращён Китаю, когда мирная передача власти привела к созданию Особого административного района Гонконг. В течение многих лет Гонконг сохранял высокую степень автономии в рамках принципа «одна страна, две системы», поддерживая отдельные правовую и экономическую системы, основанные на свободной торговле. Однако в начале XXI века Пекин усилил контроль над регионом, что вызвало политические перемены и широкую международную обеспокоенность эрозией автономии Гонконга. Несмотря на эти изменения, Гонконг остаётся мировым финансовым центром, известным своей исключительно плотной городской застройкой, узнаваемым силуэтом и яркой культурной самобытностью.'
WHERE Tag = 'TXT_KEY_CIV5_HONG_KONG_TEXT';

-- Update Singapore's Civilopedia entry to note that it's now the fourth wealthiest country by GDP per capita, not the fifth
UPDATE Language_ru_RU
SET Text = 'Исторические записи и археологические раскопки показывают, что остров современного Сингапура был заселён примерно со II века нашей эры — первоначально этот небольшой остров входил в состав Суматранской империи и носил название Темасек, или «морской город». По неизвестным причинам в XIV веке территория пришла в упадок, и в последующие несколько столетий население острова состояло в основном из маленьких рыбацких деревень.[NEWLINE][NEWLINE]Всё изменилось 29 января 1819 года, когда британский государственный деятель сэр Томас Стэмфорд Раффлз высадился на острове и подписал договор о развитии его южной части как британского торгового поста. Сингапур официально стал британской колонией в 1824 году, когда Британская Ост-Индская компания получила контроль над всем островом. Город на острове быстро рос, превращаясь в важный центр торговли и коммерции в Тихоокеанском регионе.[NEWLINE][NEWLINE]В 1941 году Япония вторглась в Сингапур и всего за шесть дней захватила город и его военную базу. Битва за Сингапур, как её позже назвали, стала крупнейшей военной катастрофой в истории Британии, а сам город на оставшееся время Второй мировой войны превратился в важную японскую базу. Британцы вернули контроль над островом через месяц после капитуляции Японии в 1945 году.[NEWLINE][NEWLINE]После войны Сингапур встал на путь независимости. В 1955 году городу разрешили провести первые всеобщие выборы, но делегации, отправленные в Англию с требованием самоуправления, встречали сопротивление вплоть до 1959 года. Четыре года спустя маленькое город-государство формально провозгласило независимость от Британской империи и вскоре вошло в Федерацию Малайзии. Однако серьёзные идеологические противоречия между Сингапуром и Федерацией испортили отношения, и ещё через два года Сингапур официально объявил о полном суверенитете.[NEWLINE][NEWLINE]После обретения независимости положение города-государства заметно улучшилось: резко вырос уровень жизни, укрепились экономика и система образования. Сегодня Сингапур — четвёртая самая богатая страна мира по ВВП на душу населения, с процветающими туристической и медицинской отраслями.'
WHERE Tag = 'TXT_KEY_CIV5_SINGAPORE_TEXT';
